import React, {memo} from 'react';
import type {ReactNode} from 'react';

import {Suggest} from '~/src/components/Suggest';
import type {SuggestProps} from '~/src/components/Suggest';

import {TagsList} from '../TagsList/TagsList';

import {cnSelectSearch} from './SelectSearch.classname';
import {useSelectSearch} from './hooks/useSelectSearch';
import type {Option} from './types';

import './SelectSearch.scss';

export type SelectSearchProps<V = string> = SuggestProps & {
    className?: string;
    mode?: 'tags';
    /** Max tag count to show */
    maxTagCount?: number;
    /** Customize tag render, only applies when mode is set to multiple or tags */
    tagRender?: (option: Option<V>) => ReactNode;
    /** Called when an option is deselected, param is the selected option's value. Only called for tags */
    onDeselect?: (value: V) => void;
    /** Current selected option */
    values: Option<V>[];
};

const SelectSearchInternal = <V,>({
    className,
    mode,
    values,
    maxTagCount,
    inputClassName,
    popupClassName,
    tagRender,
    onDeselect,
    renderItem: customRenderItem,
    ...suggestProps
}: SelectSearchProps<V>) => {
    const {renderItem} = useSelectSearch({values, customRenderItem});
    const withTags = mode === 'tags' && (Boolean(onDeselect) || Boolean(tagRender));

    return (
        <div className={cnSelectSearch(null, className)}>
            <Suggest
                autoComplete={false}
                renderItem={renderItem}
                {...suggestProps}
                inputClassName={cnSelectSearch(
                    'suggest',
                    {['mode_tags']: values.length > 0},
                    inputClassName,
                )}
                popupClassName={cnSelectSearch('popup', popupClassName)}
            />
            {withTags && (
                <div className={cnSelectSearch('tags')}>
                    <TagsList<V>
                        values={values}
                        maxTagCount={maxTagCount}
                        renderTag={tagRender}
                        onDeselect={onDeselect!}
                        tagTheme="normal"
                        tagClassName={cnSelectSearch('tag')}
                        tagSize="xs"
                    />
                </div>
            )}
        </div>
    );
};

export const SelectSearch = memo(SelectSearchInternal) as typeof SelectSearchInternal;
